// Randomized 112-pixel Duck eye blinking for the browser URDF viewer.
//
// The WebGL/URDF model exposes eye pixels using LedPixel1..LedPixel112 names.
// The layout below is the 112-LED row-major layout used by the MuJoCo viewer.
// A blink masks matching rows from the top and bottom. Timers are used rather
// than a permanent animation loop, so the idle cost is effectively zero.

export const DUCK_EYE_112_ROW_LAYOUT = Object.freeze([
  4, 8, 10, 10, 12, 12, 12, 12, 10, 10, 8, 4,
]);

const EXPECTED_PIXEL_COUNT = 112;
const PIXEL_INDEX_RE = /led[\s_.-]*pixel[\s_.-]*0*(\d+)/i;

const LED_MATERIAL_STYLE_ATTRIBUTES = Object.freeze([
  'rgba',
  'emission',
  'emissive',
  'specular',
  'shininess',
  'reflectance',
  'reflectivity',
]);

function clamp(value, low, high) {
  const number = Number(value);
  if (!Number.isFinite(number)) return low;
  return Math.max(low, Math.min(high, number));
}

function parseNumberList(value) {
  if (typeof value !== 'string') return [];
  return value
    .trim()
    .split(/[\s,]+/)
    .filter(Boolean)
    .map((part) => Number(part))
    .filter((part) => Number.isFinite(part));
}

function parseAttributes(text) {
  const result = {};
  const source = String(text || '');
  const pattern = /([A-Za-z_][\w:.-]*)\s*=\s*(["'])(.*?)\2/g;
  let match;
  while ((match = pattern.exec(source)) !== null) {
    result[String(match[1]).toLowerCase()] = match[3];
  }
  return result;
}

function normalizedColor(value, fallback = null) {
  const values = Array.isArray(value) ? value : parseNumberList(value);
  if (values.length === 1) {
    const component = clamp(values[0], 0, 1);
    return [component, component, component];
  }
  if (values.length >= 3) {
    return [
      clamp(values[0], 0, 1),
      clamp(values[1], 0, 1),
      clamp(values[2], 0, 1),
    ];
  }
  return fallback;
}

function normalizeLedMaterialStyle(style = {}) {
  if (!style || typeof style !== 'object') return null;
  const output = {};

  const rgbaValues = Array.isArray(style.rgba) ? style.rgba : parseNumberList(style.rgba);
  if (rgbaValues.length >= 3) {
    output.rgba = [
      clamp(rgbaValues[0], 0, 1),
      clamp(rgbaValues[1], 0, 1),
      clamp(rgbaValues[2], 0, 1),
      clamp(rgbaValues.length >= 4 ? rgbaValues[3] : 1, 0, 1),
    ];
  }

  const emissionSource = style.emission ?? style.emissive;
  const emissionValues = Array.isArray(emissionSource)
    ? emissionSource
    : parseNumberList(emissionSource);
  if (emissionValues.length === 1) {
    output.emissive = output.rgba ? output.rgba.slice(0, 3) : [1, 1, 1];
    output.emissiveIntensity = Math.max(0, Number(emissionValues[0]));
  } else if (emissionValues.length >= 3) {
    output.emissive = normalizedColor(emissionValues, [1, 1, 1]);
    output.emissiveIntensity = Number.isFinite(Number(style.emissiveIntensity))
      ? Math.max(0, Number(style.emissiveIntensity))
      : (emissionValues.length >= 4 ? Math.max(0, Number(emissionValues[3])) : 1);
  }

  const specular = normalizedColor(style.specular, null);
  if (specular) output.specular = specular;

  const shininess = Number(style.shininess);
  if (Number.isFinite(shininess)) {
    // The URDF extension uses normalized [0,1] shininess. Values above 1 are
    // accepted as direct Three.js MeshPhongMaterial values for convenience.
    output.shininess = Math.max(0, shininess <= 1 ? shininess * 100 : shininess);
  }

  const reflectivity = Number(style.reflectance ?? style.reflectivity);
  if (Number.isFinite(reflectivity)) output.reflectivity = clamp(reflectivity, 0, 1);

  return Object.keys(output).length ? output : null;
}

/**
 * Parse the PuddleDuck LED material extension from a URDF string.
 *
 * Standard URDF understands only a nested <color rgba="..."/> (and texture).
 * For browser rendering we additionally accept scalar/vector attributes on the
 * named material, for example:
 *
 *   <material name="LedColor" emission="1.0" specular="0.9"
 *             shininess="1.0" rgba="1 1 1 1" reflectance="1.0"/>
 *
 * The original nested-color form remains supported. These extra attributes are
 * intentionally applied only to the 112 LedPixel visuals after URDFLoader has
 * created its Three.js materials.
 */
export function parseUrdfLedMaterialStyle(urdfText, materialName = 'LedColor') {
  const source = String(urdfText || '');
  if (!source || !materialName) return null;
  const escapedName = String(materialName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const candidates = [];

  const paired = new RegExp(
    `<material\\b([^>]*\\bname\\s*=\\s*(["'])${escapedName}\\2[^>]*)>([\\s\\S]*?)<\\/material\\s*>`,
    'gi',
  );
  let match;
  while ((match = paired.exec(source)) !== null) {
    if (/\/\s*$/.test(match[1])) continue;
    const attrs = parseAttributes(match[1]);
    const colorMatch = String(match[3] || '').match(/<color\b([^>]*)\/?\s*>/i);
    if (!attrs.rgba && colorMatch) attrs.rgba = parseAttributes(colorMatch[1]).rgba;
    candidates.push(attrs);
  }

  const selfClosing = new RegExp(
    `<material\\b([^>]*\\bname\\s*=\\s*(["'])${escapedName}\\2[^>]*)\\/\\s*>`,
    'gi',
  );
  while ((match = selfClosing.exec(source)) !== null) candidates.push(parseAttributes(match[1]));

  // Prefer a declaration containing one of the rendering extension attributes
  // over the many <material name="LedColor"/> visual references.
  const selected = candidates.find((candidate) => (
    LED_MATERIAL_STYLE_ATTRIBUTES.some((name) => candidate[name] !== undefined)
  ));
  return normalizeLedMaterialStyle(selected || null);
}

export function applyLedMaterialStyle(material, style) {
  const normalized = normalizeLedMaterialStyle(style);
  if (!material || !normalized) return material;

  if (normalized.rgba) {
    material.color?.setRGB?.(...normalized.rgba.slice(0, 3));
    if ('opacity' in material) material.opacity = normalized.rgba[3];
    if ('transparent' in material) material.transparent = normalized.rgba[3] < 0.999;
  }
  if (normalized.emissive) material.emissive?.setRGB?.(...normalized.emissive);
  if (Number.isFinite(normalized.emissiveIntensity) && 'emissiveIntensity' in material) {
    material.emissiveIntensity = normalized.emissiveIntensity;
  }
  if (normalized.specular) material.specular?.setRGB?.(...normalized.specular);
  if (Number.isFinite(normalized.shininess) && 'shininess' in material) {
    material.shininess = normalized.shininess;
  }
  if (Number.isFinite(normalized.reflectivity) && 'reflectivity' in material) {
    material.reflectivity = normalized.reflectivity;
  }
  material.needsUpdate = true;
  return material;
}

function candidateNames(object) {
  const values = [
    object?.name,
    object?.geometry?.name,
    object?.material?.name,
    object?.userData?.name,
    object?.userData?.urdfName,
    object?.userData?.visualName,
    object?.userData?.meshName,
  ];
  if (Array.isArray(object?.material)) {
    for (const material of object.material) values.push(material?.name);
  }
  let parent = object?.parent;
  for (let depth = 0; parent && depth < 4; depth += 1, parent = parent.parent) {
    values.push(parent.name, parent?.userData?.name, parent?.userData?.urdfName);
  }
  return values.filter((value) => typeof value === 'string' && value.length > 0);
}

function pixelIndex(object) {
  for (const value of candidateNames(object)) {
    const match = value.match(PIXEL_INDEX_RE);
    if (!match) continue;
    const index = Number.parseInt(match[1], 10);
    if (Number.isInteger(index) && index >= 1 && index <= EXPECTED_PIXEL_COUNT) return index;
  }
  return 0;
}

function renderablesFor(object) {
  const result = [];
  const seen = new Set();
  const add = (candidate) => {
    if (!candidate?.material || seen.has(candidate)) return;
    seen.add(candidate);
    result.push(candidate);
  };
  add(object);
  object?.traverse?.(add);
  return result;
}

function cloneMaterials(object, materialStyle = null) {
  const original = object.material;
  const originals = Array.isArray(original) ? original : [original];
  if (!originals.length || originals.some((material) => !material?.clone)) return null;
  const cloned = originals.map((material) => applyLedMaterialStyle(material.clone(), materialStyle));
  object.material = Array.isArray(original) ? cloned : cloned[0];
  return {
    object,
    original,
    cloned,
    baseline: cloned.map((material) => ({
      color: material.color?.clone?.() || null,
      emissive: material.emissive?.clone?.() || null,
      emissiveIntensity: Number(material.emissiveIntensity),
      opacity: Number(material.opacity),
      transparent: material.transparent,
      specular: material.specular?.clone?.() || null,
      shininess: Number(material.shininess),
      reflectivity: Number(material.reflectivity),
      visible: material.visible,
    })),
  };
}

function setBindingOn(binding, on) {
  binding.cloned.forEach((material, index) => {
    const baseline = binding.baseline[index];
    if (on) {
      if (baseline.color && material.color?.copy) material.color.copy(baseline.color);
      if (baseline.emissive && material.emissive?.copy) material.emissive.copy(baseline.emissive);
      if (Number.isFinite(baseline.emissiveIntensity)) material.emissiveIntensity = baseline.emissiveIntensity;
      if (Number.isFinite(baseline.opacity)) material.opacity = baseline.opacity;
      if (baseline.transparent !== undefined) material.transparent = baseline.transparent;
      if (baseline.specular && material.specular?.copy) material.specular.copy(baseline.specular);
      if (Number.isFinite(baseline.shininess) && 'shininess' in material) material.shininess = baseline.shininess;
      if (Number.isFinite(baseline.reflectivity) && 'reflectivity' in material) material.reflectivity = baseline.reflectivity;
      if (baseline.visible !== undefined) material.visible = baseline.visible;
    } else {
      material.color?.setRGB?.(0, 0, 0);
      material.emissive?.setRGB?.(0, 0, 0);
      material.specular?.setRGB?.(0, 0, 0);
      if ('emissiveIntensity' in material) material.emissiveIntensity = 0;
      if ('reflectivity' in material) material.reflectivity = 0;
    }
    material.needsUpdate = true;
  });
}

function restoreBinding(binding) {
  if (!binding?.object) return;
  binding.object.material = binding.original;
  for (const material of binding.cloned || []) material?.dispose?.();
}

export function collectDuckEyePixelBindings(robot, options = {}) {
  if (!robot?.traverse) return null;
  const objectsByIndex = new Map();
  const assignedObjects = new Set();

  robot.traverse((object) => {
    const index = pixelIndex(object);
    if (!index) return;
    const renderables = renderablesFor(object).filter((candidate) => !assignedObjects.has(candidate));
    if (!renderables.length) return;
    const list = objectsByIndex.get(index) || [];
    for (const renderable of renderables) {
      assignedObjects.add(renderable);
      list.push(renderable);
    }
    objectsByIndex.set(index, list);
  });

  for (let index = 1; index <= EXPECTED_PIXEL_COUNT; index += 1) {
    if (!objectsByIndex.get(index)?.length) return null;
  }

  const result = [];
  for (let index = 1; index <= EXPECTED_PIXEL_COUNT; index += 1) {
    const bindings = [];
    for (const object of objectsByIndex.get(index)) {
      const binding = cloneMaterials(object, options.materialStyle);
      if (binding) bindings.push(binding);
    }
    if (!bindings.length) {
      for (const group of result) for (const binding of group) restoreBinding(binding);
      return null;
    }
    result.push(bindings);
  }
  return result;
}

function randomInteger(random, low, highInclusive) {
  const span = Math.max(1, (highInclusive - low) + 1);
  return low + Math.floor(Math.max(0, Math.min(0.999999999, random())) * span);
}

export class DuckEyeBlinker112 {
  constructor(viewer, bindings, options = {}) {
    if (!viewer?.robot || !bindings || bindings.length !== EXPECTED_PIXEL_COUNT) {
      throw new Error('DuckEyeBlinker112 requires a loaded viewer with 112 LED pixel bindings');
    }
    this.viewer = viewer;
    this.robot = viewer.robot;
    this.bindings = bindings;
    this.random = options.random || Math.random;
    this.setTimer = options.setTimer || ((fn, delay) => setTimeout(fn, delay));
    this.clearTimer = options.clearTimer || ((timer) => clearTimeout(timer));
    this.timer = 0;
    this.running = false;
    this.maskRows = -1;
    this.rapidCount = 0;
    this.rowForPixel = [];
    DUCK_EYE_112_ROW_LAYOUT.forEach((count, row) => {
      for (let index = 0; index < count; index += 1) this.rowForPixel.push(row);
    });
    this.maxMaskRows = Math.floor(DUCK_EYE_112_ROW_LAYOUT.length / 2);
  }

  schedule(callback, delayMs) {
    if (!this.running) return;
    if (this.timer) this.clearTimer(this.timer);
    this.timer = this.setTimer(() => {
      this.timer = 0;
      if (!this.running || this.viewer?.robot !== this.robot) {
        this.stop();
        return;
      }
      callback();
    }, Math.max(1, Math.round(delayMs)));
  }

  applyMask(rows) {
    const clamped = Math.max(0, Math.min(this.maxMaskRows, Number(rows) || 0));
    if (clamped === this.maskRows) return;
    this.maskRows = clamped;
    const rowCount = DUCK_EYE_112_ROW_LAYOUT.length;
    this.bindings.forEach((group, pixelIndexValue) => {
      const row = this.rowForPixel[pixelIndexValue];
      const on = !(row < clamped || row >= rowCount - clamped);
      for (const binding of group) setBindingOn(binding, on);
    });
    this.viewer?.redraw?.();
  }

  normalParameters() {
    return { delayMin: 1000, delayMax: 4000, closeMin: 180, closeMax: 200, interval: 20 };
  }

  rapidParameters() {
    return {
      delayMin: 100,
      delayMax: 500,
      closeMin: 10,
      closeMax: 50,
      interval: randomInteger(this.random, 5, 9),
    };
  }

  scheduleNextBlink() {
    if (!this.running) return;
    let parameters = this.normalParameters();
    if (this.rapidCount > 0) {
      this.rapidCount -= 1;
      parameters = this.rapidParameters();
    } else if (randomInteger(this.random, 0, 99) < 10) {
      this.rapidCount = randomInteger(this.random, 1, 4);
      parameters = this.rapidParameters();
    }
    const delay = randomInteger(this.random, parameters.delayMin, parameters.delayMax);
    this.schedule(() => this.closeStep(0, parameters), delay);
  }

  closeStep(rows, parameters) {
    const next = rows + 1;
    this.applyMask(next);
    if (next < this.maxMaskRows) {
      this.schedule(() => this.closeStep(next, parameters), parameters.interval);
      return;
    }
    const hold = randomInteger(this.random, parameters.closeMin, parameters.closeMax);
    this.schedule(() => this.openStep(this.maxMaskRows, parameters), hold);
  }

  openStep(rows, parameters) {
    const next = rows - 1;
    this.applyMask(next);
    if (next > 0) {
      this.schedule(() => this.openStep(next, parameters), parameters.interval);
      return;
    }
    this.scheduleNextBlink();
  }

  start() {
    if (this.running) return;
    this.running = true;
    this.applyMask(0);
    this.scheduleNextBlink();
  }

  stop({ restore = true } = {}) {
    this.running = false;
    if (this.timer) {
      this.clearTimer(this.timer);
      this.timer = 0;
    }
    if (restore) {
      for (const group of this.bindings) for (const binding of group) restoreBinding(binding);
      this.viewer?.redraw?.();
    }
    this.bindings = [];
  }
}

export function createDuckEyeBlinker112(viewer, options = {}) {
  const bindings = collectDuckEyePixelBindings(viewer?.robot, options);
  if (!bindings) return null;
  return new DuckEyeBlinker112(viewer, bindings, options);
}
